local out = {}
local function try(label, f)
  local ok, v = pcall(f)
  out[#out+1] = label .. '=' .. (ok and tostring(v) or ('ERR:' .. tostring(v)))
end
try('ruleset', function() return GameConfiguration.GetRuleSet() end)
for _, name in ipairs({'GOLDEN_AGE_SCORE_BASE_THRESHOLD','DARK_AGE_SCORE_BASE_THRESHOLD','THRESHOLD_SHIFT_PER_CITY','THRESHOLD_SHIFT_PER_PAST_GOLDEN_AGE','THRESHOLD_SHIFT_PER_PAST_DARK_AGE','COMMEMORATE_BASE_CHOICES_ALLOWED','COMMEMORATE_OPTIONS_MAX','NEXT_ERA_TURN_COUNTDOWN','LOYALTY_FROM_EXCESS_SCORE_MULTIPLIER'}) do
  try(name, function() return GlobalParameters[name] end)
end
try('eras', function() local t = {}; for row in GameInfo.Eras() do t[#t+1] = row.EraType end; return table.concat(t, ',') end)
try('eras_xp1_min_max', function() local t = {}; for row in GameInfo.Eras_XP1() do t[#t+1] = row.EraType .. ':' .. tostring(row.GameEraMinimumTurns) .. '/' .. tostring(row.GameEraMaximumTurns) end; return table.concat(t, ',') end)
try('eras_xp2_shift', function() local t = {}; for row in GameInfo.Eras_XP2() do t[#t+1] = row.EraType .. ':' .. tostring(row.EraScoreThresholdShift) end; return table.concat(t, ',') end)
try('commemorations', function() local t = {}; for row in GameInfo.CommemorationTypes() do t[#t+1] = row.CommemorationType .. '[' .. tostring(row.MinimumGameEra) .. '-' .. tostring(row.MaximumGameEra) .. ']' end; return table.concat(t, ',') end)
try('dark_golden_policies', function() local d, g = 0, 0; for row in GameInfo.Policies_XP1() do if row.RequiresDarkAge then d = d + 1 end; if row.RequiresGoldenAge then g = g + 1 end end; return d .. ' dark / ' .. g .. ' golden' end)
try('policies_total', function() local n = 0; for row in GameInfo.Policies() do n = n + 1 end; return n end)
try('age_identity_modifiers', function() local t = {}; for row in GameInfo.TraitModifiers() do if row.ModifierId == 'GOLDEN_AGE_CITY_IDENTITY' or row.ModifierId == 'DARK_AGE_CITY_IDENTITY' then t[#t+1] = row.TraitType .. '>' .. row.ModifierId end end; return table.concat(t, ',') end)
try('moment_scores', function() local t = {}; for _, id in ipairs({'MOMENT_PLAYER_MET_MAJOR','MOMENT_PLAYER_MET_ALL_MAJORS','MOMENT_CITY_TRANSFERRED_FOREIGN_CAPITAL','MOMENT_CITY_TRANSFERRED_PLAYER_DEFEATED','MOMENT_CITY_TRANSFERRED_TO_ORIGINAL_OWNER','MOMENT_WAR_DECLARED_USING_CASUS_BELLI','MOMENT_BUILDING_CONSTRUCTED_GAME_ERA_WONDER'}) do local r = GameInfo.Moments[id]; t[#t+1] = id .. '=' .. tostring(r and r.EraScore) end; return table.concat(t, ',') end)
return table.concat(out, '\n')
